import React from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";
import Button from "react-bootstrap/Button";

// Fix icona marker Leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png",
  iconUrl:
    "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png",
  shadowUrl:
    "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png",
});

const MappaClienti = ({ clienti }) => {
  const centro = [44.7, 10.8]; // centro iniziale (Correggio)

  const apriNavigazione = (lat, lng) => {
    const url = `https://www.google.com/maps/dir/?api=1&destination=${lat},${lng}`;
    window.open(url, "_blank");
  };

  return (
    <MapContainer center={centro} zoom={10} style={{ height: "600px", width: "100%" }}>
      <TileLayer
        attribution='© OpenStreetMap'
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
      />

      {clienti.map((c, i) => (
        c.lat && c.lng && (
          <Marker
            key={`${c.id}-${i}`}
            position={[c.lat, c.lng]}
            eventHandlers={{
              click: () => apriNavigazione(c.lat, c.lng),
            }}
          >
            <Popup>
              <strong>{c.ragioneSociale}</strong><br />
              {c.indirizzo}<br />
              <Button
                variant="outline-success"
                size="sm"
                className="mt-2"
                onClick={() => apriNavigazione(c.lat, c.lng)}
              >
                🧭 Naviga con Google Maps
              </Button>
            </Popup>
          </Marker>
        )
      ))}
    </MapContainer>
  );
};

export default MappaClienti;