import React, { useEffect, useState } from "react";
import { collection, getDocs, addDoc } from "firebase/firestore";
import { db } from "./firebase";
import { geolocalizzaIndirizzo } from "./utils/geolocalizzaIndirizzo";
import Container from "react-bootstrap/Container";
import Form from "react-bootstrap/Form";
import Button from "react-bootstrap/Button";
import Alert from "react-bootstrap/Alert";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require("leaflet/dist/images/marker-icon-2x.png"),
  iconUrl: require("leaflet/dist/images/marker-icon.png"),
  shadowUrl: require("leaflet/dist/images/marker-shadow.png"),
});

const NuovoIntervento = () => {
  const [clienti, setClienti] = useState([]);
  const [clienteSelezionato, setClienteSelezionato] = useState("");
  const [mezziAssociati, setMezziAssociati] = useState([]);
  const [mezzoSelezionato, setMezzoSelezionato] = useState("");

  const [indirizzo, setIndirizzo] = useState("");
  const [comune, setComune] = useState("");
  const [provincia, setProvincia] = useState("");
  const [cap, setCap] = useState("");
  const [tecnico, setTecnico] = useState("");
  const [urgenza, setUrgenza] = useState("");
  const [categoria, setCategoria] = useState("");
  const [frequenza, setFrequenza] = useState("");
  const [dataIntervento, setDataIntervento] = useState("");
  const [coordinate, setCoordinate] = useState(null);

  const [errore, setErrore] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchClienti = async () => {
      try {
        const snapshot = await getDocs(collection(db, "CLIENTI"));
        const lista = snapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));
        setClienti(lista);
      } catch (error) {
        console.error("❌ Errore nel caricamento clienti:", error);
        setErrore("Errore nel caricamento clienti.");
      }
    };
    fetchClienti();
  }, []);

  useEffect(() => {
    const fetchMezzi = async () => {
      if (!clienteSelezionato) {
        setMezziAssociati([]);
        return;
      }

      const snapshot = await getDocs(collection(db, "MEZZI"));
      const tuttiMezzi = snapshot.docs.map((doc) => ({
        id: doc.id,
        ...doc.data(),
      }));

      const filtrati = tuttiMezzi.filter(
        (m) => m.clienteFirebaseId === clienteSelezionato
      );

      setMezziAssociati(filtrati);
    };

    fetchMezzi();
  }, [clienteSelezionato]);

  useEffect(() => {
    const cliente = clienti.find((c) => c.id === clienteSelezionato);
    if (!cliente) return;

    setIndirizzo(cliente.indirizzo || "");
    setComune(cliente.comune || "");
    setProvincia(cliente.provincia || "");
    setCap(cliente.cap || "");
    setTecnico(cliente.tecnico || "");
    setUrgenza(cliente.urgenza || "media");

    if (cliente.lat && cliente.lng) {
      setCoordinate({ lat: cliente.lat, lng: cliente.lng });
    } else {
      const indirizzoCompleto = `${cliente.indirizzo}, ${cliente.cap} ${cliente.comune}, ${cliente.provincia}, Italia`;
      geolocalizzaIndirizzo(indirizzoCompleto).then((coords) => {
        if (coords) setCoordinate(coords);
      });
    }
  }, [clienteSelezionato]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    let prossimaData = null;
    let alertScadenza = false;

    if (categoria === "Manutenzione Programmata" && dataIntervento && frequenza) {
      const data = new Date(dataIntervento);
      if (frequenza === "Trimestrale") {
        data.setMonth(data.getMonth() + 3);
      } else if (frequenza === "Annuale") {
        data.setFullYear(data.getFullYear() + 1);
      }
      prossimaData = data;

      const oggi = new Date();
      const diff = prossimaData - oggi;
      const giorni = diff / (1000 * 60 * 60 * 24);
      if (giorni <= 7) {
        alertScadenza = true;
      }
    }

    const interventoData = {
      clienteId: clienteSelezionato,
      mezzoId: mezzoSelezionato,
      indirizzo,
      comune,
      provincia,
      cap,
      tecnico,
      urgenza,
      categoria,
      frequenza: frequenza || null,
      dataIntervento: dataIntervento ? new Date(dataIntervento) : null,
      prossimaManutenzione: prossimaData || null,
      alertScadenza,
      createdAt: new Date(),
      lat: coordinate?.lat,
      lng: coordinate?.lng,
    };

    try {
      await addDoc(collection(db, "INTERVENTI"), interventoData);
      setClienteSelezionato("");
      setMezzoSelezionato("");
      setIndirizzo("");
      setComune("");
      setProvincia("");
      setCap("");
      setTecnico("");
      setUrgenza("");
      setCategoria("");
      setFrequenza("");
      setDataIntervento("");
      setCoordinate(null);
    } catch (err) {
      console.error("❌ Errore salvataggio intervento:", err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container className="mt-4">
      <h3 className="mb-4">🛠️ Nuovo Intervento</h3>
      {errore && <Alert variant="danger">{errore}</Alert>}

      <Form onSubmit={handleSubmit} className="mb-4 p-3 border rounded bg-light">
        <Form.Group className="mb-3">
          <Form.Label>Cliente</Form.Label>
          <Form.Select value={clienteSelezionato} onChange={(e) => setClienteSelezionato(e.target.value)} required>
            <option value="">-- Seleziona cliente --</option>
            {clienti.map((c) => (
              <option key={c.id} value={c.id}>
                {c.ragioneSociale}
              </option>
            ))}
          </Form.Select>
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Mezzo assegnato</Form.Label>
          <Form.Select value={mezzoSelezionato} onChange={(e) => setMezzoSelezionato(e.target.value)}>
            <option value="">-- Seleziona mezzo --</option>
            {mezziAssociati.map((m) => (
              <option key={m.id} value={m.id}>
                {m.marca} {m.modello} ({m.matricola})
              </option>
            ))}
          </Form.Select>
        </Form.Group>

        <Form.Group className="mb-2">
          <Form.Label>Indirizzo</Form.Label>
          <Form.Control value={indirizzo} onChange={(e) => setIndirizzo(e.target.value)} required />
        </Form.Group>

        <Form.Group className="mb-2">
          <Form.Label>Comune</Form.Label>
          <Form.Control value={comune} onChange={(e) => setComune(e.target.value)} required />
        </Form.Group>

        <Form.Group className="mb-2">
          <Form.Label>Provincia</Form.Label>
          <Form.Control value={provincia} onChange={(e) => setProvincia(e.target.value)} required />
        </Form.Group>

        <Form.Group className="mb-2">
          <Form.Label>CAP</Form.Label>
          <Form.Control value={cap} onChange={(e) => setCap(e.target.value)} required />
        </Form.Group>

                <Form.Group className="mb-2">
          <Form.Label>Tecnico</Form.Label>
          <Form.Control value={tecnico} onChange={(e) => setTecnico(e.target.value)} />
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Urgenza</Form.Label>
          <Form.Select value={urgenza} onChange={(e) => setUrgenza(e.target.value)}>
            <option value="">-- Seleziona --</option>
            <option value="bassa">Bassa</option>
            <option value="media">Media</option>
            <option value="alta">Alta</option>
          </Form.Select>
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Categoria Intervento</Form.Label>
          <Form.Select value={categoria} onChange={(e) => setCategoria(e.target.value)} required>
            <option value="">-- Seleziona categoria --</option>
            <option value="Manutenzione Programmata">Manutenzione Programmata</option>
            <option value="Lavorazione Interna">Lavorazione Interna</option>
            <option value="Intervento Esterno">Intervento Esterno</option>
          </Form.Select>
        </Form.Group>

        {categoria === "Manutenzione Programmata" && (
          <>
            <Form.Group className="mb-3">
              <Form.Label>Frequenza</Form.Label>
              <Form.Select value={frequenza} onChange={(e) => setFrequenza(e.target.value)} required>
                <option value="">-- Seleziona frequenza --</option>
                <option value="Trimestrale">Trimestrale</option>
                <option value="Annuale">Annuale</option>
              </Form.Select>
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Data Intervento</Form.Label>
              <Form.Control
                type="date"
                value={dataIntervento}
                onChange={(e) => setDataIntervento(e.target.value)}
                required
              />
            </Form.Group>
          </>
        )}

        <Button type="submit" variant="primary" disabled={loading}>
          💾 Salva Intervento
        </Button>
      </Form>

      {/* 🗺️ Mappa del cliente */}
      <h5 className="mt-4">📍 Posizione del cliente</h5>
      {coordinate ? (
        <MapContainer center={[coordinate.lat, coordinate.lng]} zoom={15} style={{ height: "300px", width: "100%" }}>
          <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
          <Marker position={[coordinate.lat, coordinate.lng]}>
            <Popup>
              <strong>Cliente selezionato</strong><br />
              {indirizzo}, {cap} {comune} ({provincia})
            </Popup>
          </Marker>
        </MapContainer>
      ) : (
        <div className="text-muted">📍 Nessuna posizione disponibile</div>
      )}
    </Container>
  );
};

export default NuovoIntervento;