import React, { useEffect, useState } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db, auth, storage } from "firebase.js";
import { Bar, Doughnut } from "react-chartjs-2";
import GraficoTrendMensile from "./GraficoTrendMensile";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend);

const StatisticheInterventi = () => {
  const [interventi, setInterventi] = useState([]);

  useEffect(() => {
    const fetchInterventi = async () => {
      try {
        const snap = await getDocs(collection(db, "INTERVENTI"));
        const dati = snap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        setInterventi(dati);
      } catch (error) {
        console.error("Errore nel caricamento interventi:", error);
      }
    };
    fetchInterventi();
  }, []);

  const totale = interventi.length;
  const urgenti = interventi.filter(i => i.urgente).length;
  const ordinari = interventi.filter(i => i.tipo === "Ordinario").length;
  const straordinari = interventi.filter(i => i.tipo === "Straordinario").length;
  const controlli = interventi.filter(i => i.tipo === "Controllo").length;

  const tecnici = [...new Set(interventi.map(i => i.tecnico))];
  const interventiPerTecnico = tecnici.map(nome => ({
    tecnico: nome,
    count: interventi.filter(i => i.tecnico === nome).length
  }));

  const barData = {
    labels: interventiPerTecnico.map(t => t.tecnico),
    datasets: [{
      label: "Interventi per tecnico",
      data: interventiPerTecnico.map(t => t.count),
      backgroundColor: "#007bff"
    }]
  };

  const doughnutData = {
    labels: ["Ordinari", "Straordinari", "Controlli"],
    datasets: [{
      data: [ordinari, straordinari, controlli],
      backgroundColor: ["#28a745", "#ffc107", "#17a2b8"]
    }]
  };

  return (
    <div className="p-4 bg-light rounded">
      <h3 className="mb-4">📊 Statistiche Interventi</h3>

      <div className="mb-3">
        <p><strong>Totale interventi:</strong> {totale}</p>
        <p><strong>Urgenti:</strong> {urgenti} ({totale > 0 ? ((urgenti / totale) * 100).toFixed(1) : "0"}%)</p>
        <p><strong>Tecnici attivi:</strong> {tecnici.length}</p>
      </div>

      <div className="row">
        <div className="col-md-6 mb-4">
          <h5>📈 Interventi per tecnico</h5>
          <Bar data={barData} options={{ responsive: true, plugins: { legend: { display: false } } }} />
        </div>
        <div className="col-md-6 mb-4">
          <h5>🧪 Tipologie intervento</h5>
          <Doughnut data={doughnutData} options={{ responsive: true }} />
        </div>
      </div>

      <div className="mt-5">
        <h5>📅 Trend mensile interventi</h5>
        <GraficoTrendMensile />
      </div>
    </div>
  );
};

export default StatisticheInterventi;