import axios from "axios";

// ✅ La tua API Key Google Maps
const GOOGLE_API_KEY = "AIzaSyCEioYKP8rJxdsztoQ3xnJiD27k-s5Pvsg";

/**
 * Geolocalizza un indirizzo usando Google Maps Geocoding API
 * @param {string} indirizzo - Indirizzo completo (es. "Via Roma 12, 42015 Correggio, RE, Italia")
 * @returns {Promise<{ lat: number, lng: number } | null>}
 */
export async function geolocalizzaIndirizzo(indirizzo) {
  if (!indirizzo || typeof indirizzo !== "string") {
    console.warn("⚠️ Indirizzo non valido:", indirizzo);
    return null;
  }

  try {
    const response = await axios.get("https://maps.googleapis.com/maps/api/geocode/json", {
      params: {
        address: indirizzo,
        key: GOOGLE_API_KEY,
      },
    });

    const results = response.data.results;
    if (!results || results.length === 0) {
      console.warn("⚠️ Nessuna coordinata trovata per:", indirizzo);
      return null;
    }

    const location = results[0].geometry.location;
    return {
      lat: location.lat,
      lng: location.lng,
    };
  } catch (error) {
    console.error("❌ Errore nella geolocalizzazione:", error.message);
    return null;
  }
}