import { collection, getDocs, updateDoc, doc } from "firebase/firestore";
import { db } from "../firebase";
import { geolocalizzaIndirizzo } from "./geolocalizzaIndirizzo";

// 🧼 Costruisce un indirizzo pulito da un oggetto cliente
const formatIndirizzoCompleto = (c) => {
  const parts = [
    c.indirizzo?.trim(),
    c.cap?.trim(),
    c.comune?.trim(),
    c.provincia?.trim(),
    "Italia",
  ].filter(Boolean);
  return parts.join(", ");
};

// 🔄 Funzione React-safe da usare nel frontend
export const normalizzaEGeolocalizzaClienti = async (setLoading, setLog = () => {}) => {
  if (typeof setLoading !== "function" || typeof setLog !== "function") {
    console.warn("❌ Parametri non validi: setLoading o setLog non sono funzioni.");
    return;
  }

  try {
    setLoading(true);
    setLog([]);

    const snap = await getDocs(collection(db, "CLIENTI"));
    const clienti = snap.docs.map((doc) => ({
      id: doc.id,
      ref: doc.ref,
      ...doc.data(),
    }));

    let aggiornati = 0;

    for (const cliente of clienti) {
      const aggiornamenti = {};

      // 📍 Geolocalizzazione se mancano lat/lng
      if (!cliente.lat || !cliente.lng) {
        const indirizzoCompleto = formatIndirizzoCompleto(cliente);
        const coords = await geolocalizzaIndirizzo(indirizzoCompleto);
        if (coords) {
          aggiornamenti.lat = coords.lat;
          aggiornamenti.lng = coords.lng;
        } else {
          setLog((prev) => [
            ...prev,
            `⚠️ Geolocalizzazione fallita per: ${cliente.ragioneSociale}`,
          ]);
        }
      }

      // 👨‍🔧 Tecnico di default
      if (!cliente.tecnico) {
        aggiornamenti.tecnico = "Non assegnato";
      }

      // ⏱️ Urgenza di default
      if (!cliente.urgenza) {
        aggiornamenti.urgenza = "media";
      }

      if (Object.keys(aggiornamenti).length > 0) {
        await updateDoc(doc(db, "CLIENTI", cliente.id), aggiornamenti);
        setLog((prev) => [
          ...prev,
          `✅ Cliente aggiornato: ${cliente.ragioneSociale}`,
        ]);
        aggiornati++;
      } else {
        setLog((prev) => [
          ...prev,
          `🔍 Cliente già completo: ${cliente.ragioneSociale}`,
        ]);
      }

      await new Promise((r) => setTimeout(r, 500)); // ⏳ Delay leggero
    }

    setLog((prev) => [
      ...prev,
      `🎉 Normalizzazione completata. Clienti aggiornati: ${aggiornati}`,
    ]);
  } catch (error) {
    console.error("❌ Errore durante la normalizzazione:", error);
    setLog((prev) => [
      ...prev,
      "❌ Errore durante la normalizzazione. Vedi console.",
    ]);
  } finally {
    setLoading(false);
  }
};