import React, { useEffect, useState } from "react";
import { Calendar, momentLocalizer } from "react-big-calendar";
import moment from "moment";
import "react-big-calendar/lib/css/react-big-calendar.css";
import { collection, onSnapshot, updateDoc, doc } from "firebase/firestore";
import { db } from "./firebase";

const localizer = momentLocalizer(moment);

const CalendarioInterventi = () => {
  const [interventi, setInterventi] = useState([]);

  useEffect(() => {
    const unsubscribe = onSnapshot(collection(db, "INTERVENTI"), (snapshot) => {
      const dati = snapshot.docs.map((doc) => {
        const data = doc.data();

        // Usa prossimaManutenzione se disponibile, altrimenti dataIntervento
        const startDate = data.prossimaManutenzione?.toDate?.() || data.dataIntervento?.toDate?.() || new Date();
        const endDate = new Date(startDate.getTime() + 60 * 60 * 1000); // +1 ora

        return {
          id: doc.id,
          title: `${data.ragioneSociale || "Intervento"} (${data.categoria || "Generico"})`,
          start: startDate,
          end: endDate,
          allDay: false,
          resource: data,
          bgColor: data.alertScadenza ? "#ffc107" : "#3788d8",
        };
      });

      setInterventi(dati);
    });

    return () => unsubscribe();
  }, []);

  const aggiornaData = async (event, start) => {
    try {
      const ref = doc(db, "INTERVENTI", event.id);
      await updateDoc(ref, { prossimaManutenzione: start });
      console.log("✅ Data aggiornata:", start);
    } catch (error) {
      console.error("❌ Errore aggiornamento data:", error);
    }
  };

  const eventStyleGetter = (event) => {
    const backgroundColor = event.bgColor || "#3788d8";
    const style = {
      backgroundColor,
      borderRadius: "5px",
      color: "white",
      border: "none",
      padding: "4px",
    };
    return { style };
  };

  return (
    <div className="p-4">
      <h3 className="mb-3">📅 Calendario Interventi</h3>
      <Calendar
        localizer={localizer}
        events={interventi}
        startAccessor="start"
        endAccessor="end"
        style={{ height: 600 }}
        onSelectEvent={(e) => console.log("Selezionato:", e)}
        onEventDrop={({ event, start }) => aggiornaData(event, start)}
        draggableAccessor={() => true}
        eventPropGetter={eventStyleGetter}
      />
    </div>
  );
};

export default CalendarioInterventi;