import React from "react";
import { Button } from "react-bootstrap";
import jsPDF from "jspdf";
import "jspdf-autotable";

/**
 * Genera un verbale PDF per un intervento tecnico.
 * @param {Object} intervento - Dati dell'intervento
 */
const GeneraVerbale = ({ intervento }) => {
  const generaPDF = () => {
    if (!intervento || typeof intervento !== "object") {
      console.error("❌ Dati intervento non validi");
      return;
    }

    const doc = new jsPDF();
    const marginLeft = 20;
    let y = 20;

    // Titolo
    doc.setFontSize(16);
    doc.text("Verbale Intervento Tecnico", marginLeft, y);
    y += 15;

    // Dettagli principali
    doc.setFontSize(12);
    const dataIntervento = intervento.data?.toDate?.();
    doc.text(`Data: ${dataIntervento ? dataIntervento.toLocaleDateString("it-IT") : "—"}`, marginLeft, y); y += 10;
    doc.text(`Tecnico: ${intervento.tecnico || "—"}`, marginLeft, y); y += 10;
    doc.text(`Cliente: ${intervento.clienteNome || "—"}`, marginLeft, y); y += 10;
    doc.text(`Mezzo: ${intervento.mezzoId || "—"}`, marginLeft, y); y += 10;
    doc.text(`Tipo: ${intervento.tipo || "—"}`, marginLeft, y); y += 10;
    doc.text(`Urgente: ${intervento.urgente ? "Sì" : "No"}`, marginLeft, y); y += 10;
    doc.text(`Stato: ${intervento.stato || "—"}`, marginLeft, y); y += 10;

    // Note
    doc.text("Note:", marginLeft, y); y += 10;
    doc.text(intervento.note || "Nessuna", marginLeft, y, { maxWidth: 170 }); y += 20;

    // Firma
    doc.text("Firma Tecnico:", marginLeft, y); y += 10;
    doc.text(intervento.firmaTecnico || "__________________", marginLeft, y);

    // Salvataggio
    const fileName = `verbale_${intervento.id || "intervento"}.pdf`;
    doc.save(fileName);
  };

  return (
    <Button
      variant="outline-dark"
      onClick={generaPDF}
      aria-label="Genera verbale PDF"
      title="Genera verbale PDF"
    >
      🧾 Genera Verbale PDF
    </Button>
  );
};

export default GeneraVerbale;